"""Three layer-sweep panels; all visual elements are generated by matplotlib."""
from pathlib import Path
import argparse
import json
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.patches import Rectangle
from matplotlib.transforms import Bbox

ROOT = Path(__file__).resolve().parent
COLOR = '#375b89'
BACKGROUND = '#f3f8fb'
GRID = '#e3edf3'

def smooth_curve(x,y,n=800):
    """Shape-preserving cubic (PCHIP) interpolation through every data point."""
    h=np.diff(x); delta=np.diff(y)/h; m=len(y); d=np.zeros(m)
    for k in range(1,m-1):
        if delta[k-1]*delta[k]<=0:
            d[k]=0.0
        else:
            w1=2*h[k]+h[k-1]; w2=h[k]+2*h[k-1]
            d[k]=(w1+w2)/(w1/delta[k-1]+w2/delta[k])
    for k,(h0,h1,d0,d1) in enumerate([(h[0],h[1],delta[0],delta[1]),
                                      (h[-1],h[-2],delta[-1],delta[-2])]):
        s=((2*h0+h1)*d0-h0*d1)/(h0+h1)
        if s*d0<=0: s=0.0
        elif d0*d1<0 and abs(s)>3*abs(d0): s=3*d0
        d[0 if k==0 else -1]=s
    per=max(2,n//(m-1))
    xs=np.concatenate([np.linspace(x[i],x[i+1],per,endpoint=False) for i in range(m-1)]+[[x[-1]]])
    i=np.clip(np.searchsorted(x,xs,side='right')-1,0,m-2)
    t=(xs-x[i])/h[i]
    ys=((2*t**3-3*t**2+1)*y[i]+(t**3-2*t**2+t)*h[i]*d[i]
        +(-2*t**3+3*t**2)*y[i+1]+(t**3-t**2)*h[i]*d[i+1])
    return xs,ys

def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('spec',type=Path,
                  help='merged figure spec json: config plus the per-panel score series')
    p.add_argument('--out',type=Path,default=None,
                  help='output dir; default ROOT/output/<spec slug> or ROOT/output')
    args=p.parse_args()
    cfg=json.loads(args.spec.read_text())
    datasets=['OCRVQA','TextVQA','COCO']
    series=cfg['data']
    # Layer count is a property of the backbone (Qwen2.5-VL 28, LLaVA-1.5 32, Qwen3-VL 36).
    n_layers=cfg.get('n_layers') or min(len(series[d]) for d in datasets)
    model=cfg.get('model','Qwen2.5-VL-7B')
    if set(series)!=set(datasets) or any(len(series[d])!=n_layers for d in datasets):
        raise ValueError(f'Expected {n_layers} scores for each of OCRVQA, TextVQA and COCO.')
    plt.rcParams.update({'font.family':'sans-serif','font.sans-serif':['DejaVu Sans'],'font.size':13,
                         'svg.fonttype':'none','pdf.fonttype':42})
    fig,axes=plt.subplots(1,3,figsize=(12,3.38))
    fig.subplots_adjust(left=.021,right=.979,bottom=.205,top=.96,wspace=.0225)
    audit=[]
    for ax,name in zip(axes,datasets):
        x=np.arange(1,n_layers+1); y=np.array(series[name],float)
        if not np.isfinite(y).all():
            raise ValueError(f'{name}: require finite scores for layers 1..{n_layers}.')
        full=float(cfg['panels'][name]['full_score'])
        selected=int(cfg['panels'][name]['selected_layer'])
        if not 1<=selected<=n_layers or not np.isfinite(full):
            raise ValueError(f'Selected layer must be within 1-{n_layers}, full score must be finite.')
        # Independent native score scales align each Full reference at a fixed fraction of
        # panel height (.94 by default). Lower the fraction when a swept layer scores ABOVE
        # the full-cache reference, which the default headroom cannot contain.
        # Override lower_score to freeze the axis scale when comparing figure versions.
        frac=float(cfg['panels'][name].get('full_height_fraction',.94))
        if not 0<frac<=1:
            raise ValueError(f'{name}: full_height_fraction must be in (0,1].')
        lower=cfg['panels'][name].get('lower_score')
        if lower is None:
            lower=min(float(y.min()),full)-.045*max(float(np.ptp(y)),abs(full)*.05,1)
        if full<=lower or float(y.min())<lower:
            raise ValueError(f'{name}: invalid lower score boundary.')
        # headroom is reserved above BOTH the full reference and the curve peak, so
        # the top band always stays free for the Full label
        top_ref=max(full,float(y.max()))
        upper=lower+(top_ref-lower)/frac
        if float(y.max())>upper:
            raise ValueError(f'{name}: score exceeds plot range; revise lower_score or full_score.')
        ax.set_facecolor(BACKGROUND)
        ax.set_xlim(0,n_layers+1); ax.set_ylim(lower,upper)
        for gfrac in [0,.25,.5,.75]:
            ax.axhline(lower+(full-lower)*gfrac,color=GRID,lw=1,zorder=0)
        for xx in sorted({1,round(n_layers*.25),round(n_layers*.5),round(n_layers*.75),n_layers}):
            ax.axvline(xx,color=GRID,lw=1,zorder=0)
        # One independent dashed reference per axes; gaps between subplots stay blank.
        ax.axhline(full,color=COLOR,ls=(0,(4,3)),lw=1.4,zorder=2)
        # Label sits in the reserved headroom band at the top of the panel so it
        # never masks the curve or the reference line.
        ax.text(.012,.985,f'Full {full:.1f}',transform=ax.transAxes,
                color=COLOR,fontsize=16,ha='left',va='top',zorder=4,
                bbox=dict(facecolor=BACKGROUND,edgecolor='none',pad=2.2))
        # Curve passes through every layer; PCHIP only replaces straight segments.
        xs,ys=smooth_curve(x,y)
        ax.plot(xs,ys,color=COLOR,lw=2.0,zorder=3)
        ax.plot(x,y,ls='none',marker='o',markersize=4.5,markeredgewidth=0,color=COLOR,zorder=4)
        value=float(y[selected-1])
        ax.vlines(selected,lower,value,color=COLOR,ls=(0,(4,3)),lw=1.4,zorder=2)
        # Annotation pair (score + "Layer k/N") is anchored to the chosen layer. On
        # noisy sweeps the bottom band can land under a dip of the curve, so walk a
        # few (height, side) slots and keep the first whose rendered bounding box
        # misses the curve; label_side in the config is only the preferred side.
        side=cfg['panels'][name].get('label_side','left')
        if side not in ('left','right'):
            raise ValueError('label_side must be left or right.')
        alt='right' if side=='left' else 'left'
        R=full-lower
        slots=[(lower+.18*R,lower+.065*R,side),(lower+.18*R,lower+.065*R,alt),
               (lower+.36*R,lower+.24*R,side),(lower+.36*R,lower+.24*R,alt),
               (lower+.54*R,lower+.42*R,alt),(lower+.54*R,lower+.42*R,side)]
        renderer=fig.canvas.get_renderer()
        dense=ax.transData.transform(np.column_stack([xs,ys]))
        def fits(t1,t2):
            b=Bbox.union([t1.get_window_extent(renderer),t2.get_window_extent(renderer)])
            ab=ax.get_window_extent(renderer)
            if not(b.x0>=ab.x0 and b.x1<=ab.x1 and b.y0>=ab.y0 and b.y1<=ab.y1):
                return False  # would spill out of the panel (and get clipped)
            pad=2.0
            return not bool(((dense[:,0]>b.x0-pad)&(dense[:,0]<b.x1+pad)&
                             (dense[:,1]>b.y0-pad)&(dense[:,1]<b.y1+pad)).any())
        def place(vy,ly,sd):
            ha='right' if sd=='left' else 'left'
            dx=-7 if sd=='left' else 7
            t1=ax.annotate(f'{value:.1f}',(selected,vy),xytext=(dx,0),
                           textcoords='offset points',ha=ha,va='center',
                           color=COLOR,fontsize=23,fontweight='bold',zorder=5)
            t2=ax.annotate(f'Layer {selected}/{n_layers}',(selected,ly),xytext=(dx,0),
                           textcoords='offset points',ha=ha,va='center',
                           color=COLOR,fontsize=16,zorder=5)
            return t1,t2
        for vy,ly,sd in slots:
            t1,t2=place(vy,ly,sd)
            if fits(t1,t2):
                break
            t1.remove(); t2.remove()
        else:  # every slot touches the curve; keep the preferred bottom one
            place(slots[0][0],slots[0][1],slots[0][2])
        ax.set_xticks([1,n_layers]); ax.set_xticklabels(['1',str(n_layers)],color=COLOR,fontsize=14,fontweight='bold')
        ax.tick_params(axis='x',length=0,pad=7)
        ax.annotate('Layer',((n_layers+1)/2,0),xycoords=ax.get_xaxis_transform(),xytext=(0,-7),
                    textcoords='offset points',ha='center',va='top',
                    color=COLOR,fontsize=14,fontweight='bold')
        ax.set_yticks([])
        ax.set_xlabel(name,color='#164b69',fontsize=19,fontweight='bold',labelpad=8)
        for s in ax.spines.values(): s.set_visible(False)
        audit.append({'dataset':name,'full_score':full,'selected_layer':selected,'selected_score':value,
                      'lower_score':lower,'upper_score':upper,'full_height_fraction':frac,'points':len(x),
                      'interpolation':'pchip','n_layers':n_layers,'above_full_max':float(y.max()-full)})
    fig.canvas.draw()
    # Extend each panel background down to the tick labels but stop above the dataset name.
    renderer=fig.canvas.get_renderer()
    for ax in axes:
        ab=ax.get_window_extent(renderer).transformed(fig.transFigure.inverted())
        tl=min(t.get_window_extent(renderer).transformed(fig.transFigure.inverted()).y0
               for t in ax.get_xticklabels())
        xl=ax.xaxis.label.get_window_extent(renderer).transformed(fig.transFigure.inverted())
        top=(tl+xl.y1)/2
        fig.add_artist(Rectangle((ab.x0,top),ab.width,ab.y1-top,transform=fig.transFigure,
                                 facecolor=BACKGROUND,edgecolor='none',zorder=-1))
    slug=cfg.get('slug','')
    out=args.out if args.out is not None else (ROOT/'output'/slug if slug else ROOT/'output')
    out.mkdir(parents=True,exist_ok=True)
    fig.savefig(out/'figure03_layers.svg',facecolor='white')
    fig.savefig(out/'figure03_layers.pdf',facecolor='white')
    fig.savefig(out/'figure03_layers.png',dpi=600,facecolor='white')
    (out/'render_audit.json').write_text(json.dumps(
        {'data_status':model,'n_layers':n_layers,'panels':audit},indent=2))
    print(f'Created SVG, PDF and PNG ({model}, {n_layers} layers): {out}')

if __name__=='__main__':main()
